void setup() {
  pinMode(LED_BUILTIN, OUTPUT);  // Настраиваем пин как выход
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // Включаем светодиод
  delay(1000);                      // Ждём 1 секунду
  digitalWrite(LED_BUILTIN, LOW);   // Выключаем светодиод
  delay(1000);                      // Ждём 1 секунду
}
